import * as T from './vendor/three.module.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {coastPoint} from './cafe-marine.js';
export function createCafeShip(scene,pick,{getBear,onStart,onEnd}={}){
 const mount=new T.Group(),body=new T.Group(),wake=new T.Group(),holder=new T.Group();scene.add(mount,holder);mount.add(body,wake);mount.name='Going Merry cruise';
 const up=new T.Vector3(0,1,0),focus=new T.Vector3(),deck=new T.Vector3(.55,.185,.65);let supportX=NaN,supportZ=NaN;let shipModel=null;let loaded=false,phase='idle',elapsed=0,time=0,angle=-Math.PI/2,returnAngle=0,bear=null,home=null,globe=true,speed=0;
 const controls=document.createElement('nav');controls.className='ship-controls';controls.hidden=true;controls.setAttribute('aria-label','航行控制');controls.innerHTML='<button data-ship="view">全景</button><button data-ship="return">靠岸</button>';document.body.append(controls);let wide=false;
 controls.querySelector('[data-ship="view"]').onclick=()=>{wide=!wide;controls.querySelector('[data-ship="view"]').textContent=wide?'近景':'全景'};
 controls.querySelector('[data-ship="return"]').onclick=()=>{if(phase!=='sailing')return;phase='returning';returnAngle=angle+(((-Math.PI/2-angle)%(Math.PI*2)+Math.PI*2)%(Math.PI*2));if(returnAngle-angle<.03)returnAngle=angle;controls.querySelector('[data-ship="return"]').disabled=true;controls.querySelector('[data-ship="return"]').textContent='正在靠岸'};
 const foamCanvas=document.createElement('canvas');foamCanvas.width=foamCanvas.height=64;const foamCtx=foamCanvas.getContext('2d'),gradient=foamCtx.createRadialGradient(32,32,2,32,32,30);gradient.addColorStop(0,'rgba(255,255,255,.9)');gradient.addColorStop(.4,'rgba(255,255,255,.55)');gradient.addColorStop(1,'rgba(255,255,255,0)');foamCtx.fillStyle=gradient;foamCtx.fillRect(0,0,64,64);const foamMap=new T.CanvasTexture(foamCanvas);
 const foamMaterial=new T.MeshBasicMaterial({map:foamMap,color:0xe9fbf5,transparent:true,opacity:.48,depthWrite:false,side:T.DoubleSide});const particles=[];
 for(let i=0;i<70;i++){const p=new T.Mesh(new T.PlaneGeometry(.12,.26),foamMaterial.clone());p.rotation.x=-Math.PI/2;wake.add(p);particles.push(p)}
 const ready=new GLTFLoader().loadAsync('./assets/coast/going-merry.glb').then(g=>{const box=new T.Box3().setFromObject(g.scene),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()),model=new T.Group();g.scene.position.set(-center.x,-box.min.y,-center.z);model.add(g.scene);model.scale.setScalar(5.2/size.x);model.rotation.y=Math.PI/2;model.position.y=-.64;body.add(model);shipModel=model;model.traverse(o=>{if(o.isMesh){o.castShadow=o.receiveShadow=true}});pick(body,'ship');loaded=true;locate();});
 function locate(){const a=angle,n=new T.Vector3(Math.cos(a),0,Math.sin(a));if(globe){mount.position.copy(coastPoint(a,1.56,.04));const radial=mount.position.clone().sub(new T.Vector3(0,-18.25,0)).normalize();mount.quaternion.setFromUnitVectors(up,radial)}else{mount.position.set(n.x*22,-1.8,n.z*22);mount.quaternion.identity()}const tangent=new T.Vector3(-Math.sin(a),0,Math.cos(a)).applyQuaternion(mount.quaternion.clone().invert());body.rotation.y=Math.atan2(tangent.x,tangent.z);wake.rotation.y=body.rotation.y;body.position.y=Math.sin(time*1.4)*.09+Math.sin(time*2.2)*.025;body.rotation.x=Math.sin(time*1.2)*.025;body.rotation.z=Math.sin(time*.85)*.035;}
 function groundPassenger(){if(!bear||!shipModel)return;bear.body.position.set(0,0,0);bear.body.rotation.set(0,0,0);body.updateWorldMatrix(true,true);if(Math.abs(bear.avatar.position.x-supportX)>.002||Math.abs(bear.avatar.position.z-supportZ)>.002||!Number.isFinite(supportX)){const origin=body.localToWorld(new T.Vector3(bear.avatar.position.x,2.6,bear.avatar.position.z)),down=new T.Vector3(0,-1,0).transformDirection(body.matrixWorld),ray=new T.Raycaster(origin,down);const contacts=ray.intersectObject(shipModel,true).map(h=>body.worldToLocal(h.point.clone())).filter(p=>p.y>-.1&&p.y<.8);if(contacts.length)deck.y=contacts[0].y;supportX=bear.avatar.position.x;supportZ=bear.avatar.position.z;}const inverse=bear.avatar.matrixWorld.clone().invert();let foot=Infinity;for(const leg of bear.legs)leg.traverse(o=>{if(!o.isMesh)return;o.geometry.computeBoundingBox();const bounds=o.geometry.boundingBox;for(const x of [bounds.min.x,bounds.max.x])for(const y of [bounds.min.y,bounds.max.y])for(const z of [bounds.min.z,bounds.max.z]){const p=new T.Vector3(x,y,z).applyMatrix4(o.matrixWorld).applyMatrix4(inverse);foot=Math.min(foot,p.y)}});bear.avatar.position.y=deck.y-(Number.isFinite(foot)?foot*bear.avatar.scale.y:0)+.003;}
 function restore(){if(!bear)return;home.parent.add(bear.avatar);bear.avatar.position.copy(home.position);bear.avatar.quaternion.copy(home.quaternion);bear.goal=home.position.clone();bear.angle=home.yaw;bear.seatTick(false,1);bear.legs.forEach(l=>l.rotation.x=0);bear.arms.forEach(l=>l.rotation.x=0);phase='idle';controls.hidden=true;document.body.classList.remove('on-ship');onEnd?.();bear=null;}
 function start(){if(!loaded||phase!=='idle')return false;bear=getBear?.();if(!bear)return false;supportX=supportZ=NaN;onStart?.();globe=false;locate();scene.updateMatrixWorld(true);home={parent:bear.avatar.parent,position:bear.avatar.position.clone(),quaternion:bear.avatar.quaternion.clone(),yaw:bear.avatar.rotation.y,world:bear.avatar.getWorldPosition(new T.Vector3())};body.add(bear.avatar);bear.avatar.position.copy(deck).add(new T.Vector3(-.35,.108,-.15));bear.avatar.quaternion.identity();elapsed=0;phase='boarding';controls.hidden=false;document.body.classList.add('on-ship');wide=false;controls.querySelector('[data-ship="view"]').textContent='全景';const back=controls.querySelector('[data-ship="return"]');back.disabled=true;back.textContent='靠岸';return true;}
 return {ready,focus,body,start,get active(){return phase!=='idle'},get wide(){return wide},owns:b=>b===bear,setOverview(value){if(!this.active)globe=value},tick(dt,t){time=t;if(!loaded)return;elapsed+=dt;if(phase!=='idle')globe=wide;if(phase==='sailing'||phase==='returning'){speed=T.MathUtils.damp(speed,phase==='returning'?Math.min(1,(returnAngle-angle)*12):1,1.3,dt);angle+=dt*.055*speed;if(phase==='returning'&&returnAngle-angle<.004){angle=returnAngle;wide=false;globe=false;locate();phase='disembarking';elapsed=0;holder.attach(bear.avatar);home.depart=bear.avatar.position.clone();speed=0}}else speed=T.MathUtils.damp(speed,0,2,dt);locate();
 if(phase==='boarding'){const u=Math.min(1,elapsed/2),e=u*u*(3-2*u);bear.avatar.position.copy(deck).add(new T.Vector3(-.35*(1-e),.108,-.15*(1-e)));bear.avatar.rotation.y=.45;bear.seatTick(false,dt);bear.legs.forEach((l,i)=>l.rotation.x=Math.sin(t*8+i*Math.PI)*.2*(1-u));if(u===1){bear.avatar.position.copy(deck);bear.avatar.position.y+=.108;bear.avatar.quaternion.identity();phase='sailing';elapsed=0;controls.querySelector('[data-ship="return"]').disabled=false}}

 if(phase==='sailing'||phase==='returning'){bear.seatTick(false,dt);bear.arms.forEach((a,i)=>a.rotation.x=-.13+Math.sin(t*1.4+i)*.03);bear.legs.forEach(l=>l.rotation.x=0)}
 if(phase==='boarding'||phase==='sailing'||phase==='returning')groundPassenger();
 if(phase==='disembarking'){const u=Math.min(1,elapsed/4),e=u*u*(3-2*u);bear.avatar.position.copy(home.depart).add(new T.Vector3(-.3*e,0,-.12*e));bear.legs.forEach((l,i)=>l.rotation.x=Math.sin(t*8+i*Math.PI)*.16);if(u===1)restore()}
 particles.forEach((p,i)=>{const u=(t*(.45+speed*.8)+i*.618)%1,side=i%2?1:-1;if(i<26){p.position.set(side*(.35+u*.8),.035+Math.sin(u*Math.PI)*.10,2.35-u*1.7);p.scale.setScalar(.5+u*1.8)}else{p.position.set(side*(.22+u*1.7),.01,-2-u*5);p.scale.set(1+u*4,1+u*2,1)}p.material.opacity=speed*(1-u)*.48;p.visible=speed>.03});
 if(bear)focus.copy(bear.avatar.getWorldPosition(new T.Vector3()));},state:()=>({phase,loaded,angle,speed,wide,position:mount.position.toArray(),deck:deck.toArray()}),dispose(){restore();controls.remove();}};
}
